template <class Engine, class Layout, class T>
CUTE_HOST_DEVICE
auto
fill(Tensor<Engine, Layout>& tensor, T const& value, prefer<1>)
    -> decltype(fill(tensor.data(), value))
{
  fill(tensor.data(), value);
}

